CREATE COLUMN TABLE "TEST_AP"."RDFL" ("DoumntDode" NVARCHAR(4) NOT NULL , "UserId" INTEGER CS_INT NOT NULL , "DfltReport" NVARCHAR(8), "CardCode" NVARCHAR(15) DEFAULT '-1' NOT NULL , "DfltSeq" INTEGER CS_INT, "TYPE" NVARCHAR(1) DEFAULT 'L', PRIMARY KEY ("DoumntDode", "UserId", "CardCode")) UNLOAD PRIORITY 0  AUTO MERGE ;
CREATE INDEX "RDFL_CODE" ON "TEST_AP"."RDFL" ( "DoumntDode" ASC )